2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (non-hard) duplicate on the owner being created. A household duplicate — the same
10	 * deterministic {@code householdId} (same last name and postcode) as an existing owner — is already
11	 * rejected with 409 by {@link EnsureUniqueIdentity} before this step runs, unless the request opted
12	 * into a shared household with {@code sharesHousehold}. This step then looks for an existing owner that
13	 * shares this owner's normalized last name and postcode but has a <em>different</em> telephone: such an
14	 * owner is still created, but is marked {@code possibleDuplicate = true} with {@code possibleDuplicateOf}
15	 * set to the matching owner's id. When no such owner exists, {@code possibleDuplicate} is {@code false}.
16	 *
17	 * <p>A declared household member (created with {@code sharesHousehold} true) is never a suspected
18	 * duplicate, so it is never flagged.
19	 *
20	 * <p>Runs after {@link BuildOwner} (so the owner already carries the normalized E.164 telephone and
21	 * the postcode) and before {@link SaveOwner}.
22	 */
23	public class AssignPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
26	        owner.setPossibleDuplicate(false);
27	        owner.setPossibleDuplicateOf(null);
28	
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return; // a declared household member is not a suspected duplicate
31	        }
32	
33	        String postcode = normalizePostcode(owner.getPostcode());
34	        if (postcode == null) {
35	            return; // no postcode means it cannot share a postcode with anyone
36	        }
37	        String lastName = HouseholdId.normalizeName(owner.getLastName());
38	        String telephone = E164Telephone.toE164OrNull(owner.getTelephone());
39	
40	        for (Owner existing : ownerRepository.findAll()) {
41	            if (existing.isDeleted()) {
42	                continue; // a soft-deleted owner is ignored by the identity check
43	            }
44	            if (!postcode.equals(normalizePostcode(existing.getPostcode()))) {
45	                continue;
46	            }
47	            if (!lastName.equals(HouseholdId.normalizeName(existing.getLastName()))) {
48	                continue;
49	            }
50	            String existingTelephone = E164Telephone.toE164OrNull(existing.getTelephone());
51	            if (telephone != null && telephone.equals(existingTelephone)) {
52	                continue; // same telephone is a hard duplicate concern, not a soft match
53	            }
54	            owner.setPossibleDuplicate(true);
55	            owner.setPossibleDuplicateOf(existing.getId());
56	            return;
57	        }
58	    }
59	
60	    private static String normalizePostcode(String postcode) {
61	        if (postcode == null) {
62	            return null;
63	        }
64	        String trimmed = postcode.trim();
65	        return trimmed.isEmpty() ? null : trimmed;
66	    }
67	}
