3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * SHA-256 rendered as lower-case hexadecimal. The full digest is 64 hex characters; callers that
9	 * want a shorter, upper-cased form (as the deterministic {@link HouseholdId} does) take a prefix and
10	 * upper-case it themselves. Keeping the primitive in one place lets the several derived identifiers in
11	 * this package share exactly one hashing implementation.
12	 */
13	final class Sha256Hex {
14	
15	    private Sha256Hex() {
16	    }
17	
18	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value} (64 characters). */
19	    static String of(String value) {
20	        try {
21	            byte[] digest = MessageDigest.getInstance("SHA-256")
22	                    .digest(value.getBytes(StandardCharsets.UTF_8));
23	            StringBuilder sb = new StringBuilder(digest.length * 2);
24	            for (byte b : digest) {
25	                sb.append(String.format("%02x", b));
26	            }
27	            return sb.toString();
28	        }
29	        catch (NoSuchAlgorithmException e) {
30	            throw new IllegalStateException("SHA-256 unavailable", e);
31	        }
32	    }
33	}
